public class KeyPairTest {

    @Test
    public void newKeyPairFromPublicKey_ReturnsNewKeyPair() {
        byte[] publicKey = {1, 2, 3};
        KeyPair keyPair = KeyPair.fromPublicKey(publicKey);
        assertNotNull(keyPair);
    }

    @Test
    public void newKeyPairFromAccountId_ReturnsCorrectKeyPair() throws GeneralSecurityException {
        String accountId = "some_account_id";
        KeyPair keyPair = KeyPair.fromAccountId(accountId);
        assertEquals(accountId, keyPair.getAccountId());
    }

    @Test
    public void fromSecretSeed_Bip39Seed_ReturnsCorrectKeyPair() {
        byte[] bip39Seed = {4, 5, 6};
        int accountNumber = 7;
        KeyPair keyPair = KeyPair.fromBip39Seed(bip39Seed, accountNumber);
        assertNotNull(keyPair);
    }

    @Test
    public void fromXdrPublicKey_ReturnsCorrectKeyPair() {
        PublicKey key = new PublicKey();
        key.setPublicKey(new Uint256(1));
        KeyPair keyPair = KeyPair.fromXdrPublicKey(key);
        assertNotNull(keyPair);
    }

    @Test
    public void sign_ReturnsSignatureForGivenData() throws GeneralSecurityException, SignatureException {
        byte[] data = {8, 9, 10};
        byte[] signature = new byte[]{11, 12, 13};
        KeyPair keyPair = new KeyPair(new EdDSAPublicKey());
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        XdrDataOutputStream xdr = new XdrDataOutputStream(bos);
        keyPair.sign(data, xdr);
        bos.flush();
        byte[] expectedSignature = {11, 12, 13};
        assertEquals(Arrays.copyOf(expectedSignature, expectedSignature.length), Arrays.copyOf(signature, signature.length));
    }

    @Test
    public void verify_ReturnsTrueForCorrectSignature() {
        byte[] data = new byte[]{14, 15, 16};
        byte[] signature = new byte[]{17, 18, 19};
        KeyPair keyPair = new KeyPair(new EdDSAPublicKey());
        assertTrue(keyPair.verify(data, signature));
    }

    @Test
    public void hashCode_ReturnsUniqueHashCode() {
        KeyPair keyPair1 = new KeyPair(new EdDSAPublicKey());
        KeyPair keyPair2 = new KeyPair(new EdDSAPublicKey());
        assertNotEquals(keyPair1.hashCode(), keyPair2.hashCode());
    }
}
